//! SQLite scalar function parity tests.
//!
//! These tests compare RedlineDB against the bundled rusqlite oracle. For
//! nondeterministic functions such as `randomblob`, the query projects stable
//! properties like type and length instead of comparing generated bytes.

#[path = "parity_oracle/harness.rs"]
mod harness;

fn assert_scalar_parity(sql: &str) {
    harness::assert_parity(sql);
}

// -- substr -----------------------------------------------------------------

#[test]
fn substr_basic_1based() {
    assert_scalar_parity("SELECT substr('hello', 2)");
}

#[test]
fn substr_with_length() {
    assert_scalar_parity("SELECT substr('hello', 2, 3)");
}

#[test]
fn substr_negative_start() {
    assert_scalar_parity("SELECT substr('hello', -3)");
}

#[test]
fn substr_zero_start_acts_as_one() {
    assert_scalar_parity("SELECT substr('hello', 0, 3)");
}

#[test]
fn substr_null_propagates() {
    assert_scalar_parity("SELECT substr(NULL, 1), substr('hi', NULL)");
}

#[test]
fn substr_alias_substring() {
    assert_scalar_parity("SELECT substring('hello', 2, 3)");
}

#[test]
fn substr_beyond_length_returns_empty() {
    assert_scalar_parity("SELECT substr('hi', 10)");
}

// -- instr ------------------------------------------------------------------

#[test]
fn instr_found() {
    assert_scalar_parity("SELECT instr('hello world', 'world')");
}

#[test]
fn instr_not_found() {
    assert_scalar_parity("SELECT instr('hello', 'xyz')");
}

#[test]
fn instr_null_propagates() {
    assert_scalar_parity("SELECT instr(NULL, 'x'), instr('x', NULL)");
}

#[test]
fn instr_empty_needle_returns_one() {
    assert_scalar_parity("SELECT instr('hello', '')");
}

// -- trim / ltrim / rtrim ----------------------------------------------------

#[test]
fn trim_whitespace() {
    assert_scalar_parity("SELECT trim('  hello  ')");
}

#[test]
fn trim_custom_chars() {
    assert_scalar_parity("SELECT trim('***hello***', '*')");
}

#[test]
fn ltrim_whitespace() {
    assert_scalar_parity("SELECT ltrim('  hi  ')");
}

#[test]
fn rtrim_whitespace() {
    assert_scalar_parity("SELECT rtrim('  hi  ')");
}

#[test]
fn trim_null_propagates() {
    assert_scalar_parity("SELECT trim(NULL)");
}

// -- replace ----------------------------------------------------------------

#[test]
fn replace_basic() {
    assert_scalar_parity("SELECT replace('hello world', 'world', 'Rust')");
}

#[test]
fn replace_all_occurrences() {
    assert_scalar_parity("SELECT replace('aababab', 'ab', 'X')");
}

#[test]
fn replace_null_propagates() {
    assert_scalar_parity(
        "SELECT replace(NULL, 'a', 'b'), replace('a', NULL, 'b'), replace('a', 'a', NULL)",
    );
}

// -- printf / format ---------------------------------------------------------

#[test]
fn printf_string_placeholder() {
    assert_scalar_parity("SELECT printf('Hello, %s!', 'world')");
}

#[test]
fn printf_integer_placeholder() {
    assert_scalar_parity("SELECT printf('%d bottles', 99)");
}

#[test]
fn printf_hex_placeholder() {
    assert_scalar_parity("SELECT printf('%x', 255)");
}

#[test]
fn printf_percent_escape() {
    assert_scalar_parity("SELECT printf('100%%')");
}

#[test]
fn format_is_alias_for_printf() {
    assert_scalar_parity("SELECT format('%d + %d = %d', 1, 2, 3)");
}

#[test]
fn printf_null_format_returns_null() {
    assert_scalar_parity("SELECT printf(NULL)");
}

