// -- randomblob -------------------------------------------------------------

#[test]
fn randomblob_correct_length() {
    assert_scalar_parity("SELECT typeof(randomblob(16)), length(randomblob(16))");
}

#[test]
fn randomblob_produces_blob_of_right_size() {
    assert_scalar_parity("SELECT typeof(randomblob(8)), length(randomblob(8))");
}

// -- functions in column expressions after INSERT ---------------------------

#[test]
fn scalar_funcs_in_select_after_insert() {
    assert_scalar_parity(
        "CREATE TABLE t(name TEXT);
         INSERT INTO t VALUES ('  hello  ');
         SELECT trim(name) FROM t",
    );
}

#[test]
fn replace_in_where_clause() {
    assert_scalar_parity(
        "CREATE TABLE t(id INTEGER, val TEXT);
         INSERT INTO t VALUES (1, 'foo'), (2, 'bar');
         SELECT id FROM t WHERE replace(val, 'foo', 'baz') = 'baz'",
    );
}

// -- real to text coercion parity -------------------------------------------

#[test]
fn lower_upper_of_real_keeps_trailing_zero() {
    for v in [1.0f64, 22.0, 7.0, 1.5, 12.25] {
        assert_scalar_parity(&format!("SELECT lower(CAST({v} AS REAL))"));
        assert_scalar_parity(&format!("SELECT upper(CAST({v} AS REAL))"));
    }
}

#[test]
fn cast_real_as_text_keeps_trailing_zero() {
    for v in [1.0f64, 0.0, -3.0, 22.5, 100.0] {
        assert_scalar_parity(&format!("SELECT CAST(CAST({v} AS REAL) AS TEXT)"));
    }
}
